import csv, statistics
from collections import defaultdict
ts_map={}
with open(CATALOG_CSV) as f:
    for row in csv.DictReader(f):
        ts_map[row['timeseries_id']]=row['point_uri'].split('#')[1]
temp={}
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        n=ts_map.get(row['timeseries_id'])
        if n and n.endswith('Zone_Air_Temperature_Sensor'):
            temp.setdefault(n,[]).append((row['timestamp'],float(row['value'])))
for k in temp: temp[k].sort()

names=['Zone_F2_Z01.Zone_Air_Temperature_Sensor','Zone_F3_Z01.Zone_Air_Temperature_Sensor',
 'Zone_F3_Z02.Zone_Air_Temperature_Sensor','Zone_F4_Z01.Zone_Air_Temperature_Sensor']
print("overall stdev/mean/min/max and daily diurnal range")
for n in names:
    vals=[v for t,v in temp[n]]
    mean=statistics.mean(vals); sd=statistics.pstdev(vals)
    # diurnal: avg of max over each day
    days=defaultdict(list)
    for t,v in temp[n]: days[t[:10]].append(v)
    dr=[max(v) for v in days.values()]
    print(n, 'mean=%.3f sd=%.3f min=%.2f max=%.2f  avgDayMax=%.2f'% (mean,sd,min(vals),max(vals),statistics.mean(dr)))

